<?php
namespace App\Http\Controllers\Public;
use App\Http\Controllers\Controller;use App\Models\Inquiry;use App\Models\SiteSetting;use Illuminate\Http\Request;use Illuminate\Support\Facades\Mail;use Illuminate\Support\Facades\Log;
class InquirySubmissionController extends Controller { public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:180','subject'=>'nullable|string|max:180','message'=>'required|string|max:5000','website'=>'nullable|max:0']);$inquiry=Inquiry::create(collect($d)->except('website')->all());$to=SiteSetting::valueFor('notification_email');if($to){try{Mail::raw("New birthday website inquiry\nFrom: {$inquiry->name} ({$inquiry->email})\nSubject: {$inquiry->subject}\n\n{$inquiry->message}",function($m)use($to,$inquiry){$m->to($to)->subject('New website inquiry: '.($inquiry->subject?:'Birthday website'));$m->replyTo($inquiry->email,$inquiry->name);});}catch(\Throwable $e){Log::warning('Inquiry notification email could not be sent',['inquiry_id'=>$inquiry->id,'error'=>$e->getMessage()]);}}return back()->with('inquiry_status','Your message has been received. Thank you!');} }
